import math
from typing import TypeVar, Generic, Union
from dataclasses import dataclass

# 1. Defines an Option type (Some/None, or equivalent)
T = TypeVar('T')

@dataclass(frozen=True)
class Some(Generic[T]):
    value: T

class _None:
    pass

Nothing = _None()

Option = Union[Some[T], _None]

# 2. Implements a safe square root function that returns Option[Float]
def safe_sqrt(n: float) -> Option[float]:
   """
   Calculates the square root of a non-negative number.
   - Returns Some(sqrt(n)) if n >= 0
   - Returns Nothing if n < 0 (can't take sqrt of negative)
   """
   if n >= 0:
       return Some(math.sqrt(n))
   else:
       return Nothing

def main():
    """
    Tests the safe_sqrt function and prints the results.
    """
    # 3. Tests the function with: safeSqrt(16.0) and safeSqrt(-4.0)
    test_cases = [16.0, -4.0]

    for case in test_cases:
        result = safe_sqrt(case)

        # 4. Prints the results
        if isinstance(result, Some):
            # For Some(value): print "Root: {value}"
            print(f"Root: {result.value}")
        else:
            # For None: print "Error: Negative input"
            print("Error: Negative input")

if __name__ == "__main__":
    main()

