from typing import Union, Optional

class Leaf:
    """Represents a leaf node in the binary tree."""
    def __init__(self, value: int):
        self.value = value

class Branch:
    """Represents a branch node in the binary tree."""
    def __init__(self, left: 'Tree', value: int, right: 'Tree'):
        self.left = left
        self.value = value
        self.right = right

Tree = Optional[Union[Leaf, Branch]]

def treeSum(tree: Tree) -> int:
    """Recursively sums all values in the tree."""
    if tree is None:
        return 0
    if isinstance(tree, Leaf):
        return tree.value
    if isinstance(tree, Branch):
        return tree.value + treeSum(tree.left) + treeSum(tree.right)
    return 0

def main():
    """Builds the tree and prints the sum of its values."""
    # Create the tree structure:
    #         5
    #        / \
    #       3   8
    #      / \   \
    #     1   4   10
    tree = Branch(
        Branch(Leaf(1), 3, Leaf(4)),
        5,
        Branch(None, 8, Leaf(10))
    )

    # Calculate and print the sum of all values
    total = treeSum(tree)
    print(total)

if __name__ == "__main__":
    main()

