import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray, filterStrings)
import std/option (Option, Some, None)
import std/result (Result, Ok, Err)
import std/string (chars)
import std/list (length, filter)

pure func countDots(s: string) -> int {
  let cs = chars(s);
  let dots = filter(\c. c == ".", cs);
  length(dots)
}

pure func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validateVersion(version: string) -> bool =
  countDots(version) == 2

pure func validateFeatures(features: [string]) -> bool =
  length(features) > 0

export func main() -> () ! {IO, FS} {
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", configJson);
  let content = readFile("app_config.json");
  match decode(content) {
    Ok(obj) => {
      let maybeName = getString(obj, "app_name");
      let maybeVersion = getString(obj, "version");
      let maybePort = getInt(obj, "port");
      let maybeFeatures = getArray(obj, "features");
      match maybeName {
        Some(appName) => match maybeVersion {
          Some(version) => match maybePort {
            Some(port) => match maybeFeatures {
              Some(featuresJson) => {
                let features = filterStrings(featuresJson);
                let portValid = validatePort(port);
                let versionValid = validateVersion(version);
                let featuresValid = validateFeatures(features);
                if portValid && versionValid && featuresValid then {
                  let count = length(features);
                  println("Loaded " ++ appName ++ " v" ++ version ++ " on port " ++ show(port) ++ " with " ++ show(count) ++ " features")
                } else if not portValid then println("Validation error: Port out of range")
                else if not versionValid then println("Validation error: Version must be X.Y.Z format")
                else println("Validation error: Features list must not be empty")
              },
              None => println("Missing features field")
            },
            None => println("Missing port field")
          },
          None => println("Missing version field")
        },
        None => println("Missing app_name field")
      }
    },
    Err(e) => println("JSON parse error: " ++ e)
  }
}

