pure func parseRow(row: string) -> Option[{name: string, age: int, email: string}] {
  let parts = split(row, ",");
  match parts {
    name :: ageStr :: email :: [] => {
      let nName = trim(name);
      let nAgeStr = trim(ageStr);
      let nEmail = trim(email);
      match stringToInt(nAgeStr) {
        Some(age) => if age > 0 && contains(nEmail, "@") then Some({name: nName, age: age, email: nEmail}) else None,
        None => None
      }
    },
    _ => None
  }
}

pure func collectValid(rows: [string]) -> [{name: string, age: int, email: string}] =
  match rows {
    [] => [],
    row :: rest => {
      match parseRow(row) {
        Some(r) => r :: collectValid(rest),
        None => collectValid(rest)
      }
    }
  }

pure func rowToJson(r: {name: string, age: int, email: string}) -> Json =
  jo([kv("name", js(r.name)), kv("age", jnum(intToFloat(r.age))), kv("email", js(r.email))])

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);
  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let dataLines = match lines { [] => [], _ :: rest => rest };
  let valid = collectValid(dataLines);
  let jsonItems = map(rowToJson, valid);
  let jsonStr = encode(ja(jsonItems));
  writeFile("users.json", jsonStr);
  println("Converted " ++ show(length(valid)) ++ " valid rows to users.json")
}

