from typing import TypeVar, Generic, Union
from dataclasses import dataclass

T = TypeVar('T')
E = TypeVar('E')

@dataclass
class Ok(Generic[T]):
    value: T

@dataclass
class Err(Generic[E]):
    message: E

Result = Union[Ok[T], Err[E]]

def validate_age(age: int) -> Result[int, str]:
    if 0 <= age <= 150:
        return Ok(age)
    else:
        return Err("Age out of range")

def calculate_retirement_years(age: int) -> Result[int, str]:
    if age < 65:
        return Ok(65 - age)
    else:
        return Err("Already retired")

def get_retirement_info(age: int) -> Result[int, str]:
    validation_result = validate_age(age)
    if isinstance(validation_result, Err):
        return validation_result

    # We know it's Ok, so we can access .value
    validated_age = validation_result.value
    return calculate_retirement_years(validated_age)

def main():
    test_ages = [30, 70, -5]
    for age in test_ages:
        result = get_retirement_info(age)
        if isinstance(result, Ok):
            print(f"Years to retirement: {result.value}")
        else:
            print(f"Error: {result.message}")

if __name__ == "__main__":
    main()

