from abc import ABC, abstractmethod

class Expr(ABC):
    @abstractmethod
    def eval(self) -> int:
        pass

class Num(Expr):
    def __init__(self, value: int):
        self.value = value

    def eval(self) -> int:
        return self.value

class Add(Expr):
    def __init__(self, left: Expr, right: Expr):
        self.left = left
        self.right = right

    def eval(self) -> int:
        return self.left.eval() + self.right.eval()

class Mul(Expr):
    def __init__(self, left: Expr, right: Expr):
        self.left = left
        self.right = right

    def eval(self) -> int:
        return self.left.eval() * self.right.eval()

def main():
    # Construct the expression: (3 + 4) * (2 + 5)
    # As an AST: Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))
    expression_ast = Mul(
        Add(Num(3), Num(4)),
        Add(Num(2), Num(5))
    )

    # Evaluate the expression
    result = expression_ast.eval()

    # Print the result
    print(result)

if __name__ == "__main__":
    main()

