-- Generic foldl implementation
-- f: binary function taking accumulator and current element
-- acc: initial accumulator value
-- xs: list to traverse
pure func foldl(f: (b, a) -> b, acc: b, xs: [a]) -> b =
  match xs {
    [] => acc,
    head :: tail => foldl(f, f(acc, head), tail)
  }

export func main() -> () ! {IO} {
  let nums = [1, 2, 3, 4, 5];
  let mixed = [3, 1, 4, 1, 5, 9, 2, 6];

  -- 1. Sum: 0 + 1 + 2 + ...
  let sum = foldl(\acc x. acc + x, 0, nums);

  -- 2. Product: 1 * 1 * 2 * ...
  let product = foldl(\acc x. acc * x, 1, nums);

  -- 3. Max: compare accumulator with current, keep larger
  let maxVal = foldl(\acc x. if x > acc then x else acc, 0, mixed);

  println("Sum: " ++ show(sum));
  println("Product: " ++ show(product));
  println("Max: " ++ show(maxVal))
}

