    [] => [],
    entry :: rest => match entry {
      (n, neighbors) => if n == node then neighbors else getNeighbors(node, rest)
    }
  }

pure func filterUnvisited(xs: [int], visited: [int]) -> [int] =
  match xs {
    [] => [],
    h :: rest => if contains(h, visited) then filterUnvisited(rest, visited) else h :: filterUnvisited(rest, visited)
  }

pure func bfsLoop(queue: [int], visited: [int], graph: [(int, [int])]) -> [int] =
  match queue {
    [] => visited,
    node :: rest => {
      if contains(node, visited) then bfsLoop(rest, visited, graph)
      else {
        let newVisited = visited ++ [node];
        let neighbors = getNeighbors(node, graph);
        let unvisited = filterUnvisited(neighbors, newVisited);
        let newQueue = enqueue(unvisited, rest);
        bfsLoop(newQueue, newVisited, graph)
      }
    }
  }

pure func bfs(start: int, graph: [(int, [int])]) -> [int] =
  bfsLoop([start], [], graph)

func printList(xs: [int]) -> () ! {IO} =
  match xs {
    [] => (),
    x :: rest => {
      println(show(x));
      printList(rest)
    }
  }

export func main() -> () ! {IO} {
  let graph = [(1, [2, 3]), (2, [4]), (3, [4, 5]), (4, []), (5, [])];
  let result = bfs(1, graph);
  printList(result)
}

