from dataclasses import dataclass
from typing import Union


@dataclass
class TVar:
    name: str


@dataclass
class TLam:
    var: str
    body: 'Term'


@dataclass
class TApp:
    func: 'Term'
    arg: 'Term'


Term = Union[TVar, TLam, TApp]


def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        if term.name == var:
            return replacement
        else:
            return term
    elif isinstance(term, TLam):
        if term.var == var:
            return term
        else:
            return TLam(term.var, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))


def eval_term(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    elif isinstance(term, TLam):
        return term
    elif isinstance(term, TApp):
        func = eval_term(term.func)
        arg = eval_term(term.arg)
        if isinstance(func, TLam):
            body = subst(func.body, func.var, arg)
            return eval_term(body)
        else:
            return TApp(func, arg)


def main():
    expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    result = eval_term(expr)
    if isinstance(result, TVar):
        print(result.name)
    else:
        print(result)


if __name__ == "__main__":
    main()

