def merge(xs: list[int], ys: list[int]) -> list[int]:
    """Merges two sorted lists into one sorted list."""
    result: list[int] = []
    i, j = 0, 0

    while i < len(xs) and j < len(ys):
        if xs[i] < ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1

    result.extend(xs[i:])
    result.extend(ys[j:])
    return result

def split(xs: list[int]) -> tuple[list[int], list[int]]:
    """Splits a list into two halves."""
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]

def mergeSort(xs: list[int]) -> list[int]:
    """Recursively sorts a list using the merge sort algorithm."""
    if len(xs) <= 1:
        return xs

    left, right = split(xs)
    sorted_left = mergeSort(left)
    sorted_right = mergeSort(right)

    return merge(sorted_left, sorted_right)

def main():
    """Main function to sort the list and print the result."""
    unsorted_list = [38, 27, 43, 3, 9, 82, 10]
    sorted_list = mergeSort(unsorted_list)
    print(sorted_list)

if __name__ == "__main__":
