from dataclasses import dataclass
from typing import Union

@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    var: str
    value: 'Expr'
    body: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]

def lookup(name, env):
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise NameError(f"Variable {name} not found")

def eval(expr, env):
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        return eval(expr.left, env) + eval(expr.right, env)
    elif isinstance(expr, Mul):
        return eval(expr.left, env) * eval(expr.right, env)
    elif isinstance(expr, Let):
        val = eval(expr.value, env)
        new_env = env + [(expr.var, val)]
        return eval(expr.body, new_env)

def main():
    program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))
    result = eval(program, [])
    print(result)

if __name__ == "__main__":
