module benchmark/solution

import std/list (foldl)

// 1. Define Color
type Color = Red | Black

// 2. Define RBTree
type RBTree = Empty | Node(Color, RBTree, int, RBTree)

// 3. Implement balance to fix red-red violations
pure func balance(c: Color, l: RBTree, v: int, r: RBTree) -> RBTree =
  match (c, l, v, r) {
    // Case 1: Left-Left violation
    (Black, Node(Red, Node(Red, a, x, b), y, c), z, d) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),

    // Case 2: Left-Right violation
    (Black, Node(Red, a, x, Node(Red, b, y, c)), z, d) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),

    // Case 3: Right-Right violation
    (Black, a, x, Node(Red, b, y, Node(Red, c, z, d))) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),

    // Case 4: Right-Left violation
    (Black, a, x, Node(Red, Node(Red, b, y, c), z, d)) =>
      Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),

    // Default case: no violation, construct node as is
    (color, left, value, right) =>
      Node(color, left, value, right)
  }

// Internal recursive insertion helper
pure func ins(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(c, l, v, r) =>
      if x < v then balance(c, ins(x, l), v, r)
      else if x > v then balance(c, l, v, ins(x, r))
      else tree // Value already exists, return original tree
  }

// 4. Implement public insert, which recolors the root to black
pure func insert(x: int, tree: RBTree) -> RBTree =
  match ins(x, tree) {
    Node(_, l, v, r) => Node(Black, l, v, r),
    Empty => Empty // Should not be reached, but handles completeness
  }

// 5. Implement inorder traversal to get sorted values
pure func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, l, v, r) => inorder(l) ++ [v] ++ inorder(r)
  }

export func main() -> () ! {IO} {
  // 6. Insert specified values
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let initialTree: RBTree = Empty;

  let finalTree = foldl(
    func(currentTree: RBTree, value: int) -> RBTree {
      insert(value, currentTree)
    },
    initialTree,
    values
  );

  // 7. Print the inorder traversal
  let sortedList = inorder(finalTree);
  println(show(sortedList));
}

