from __future__ import annotations
from dataclasses import dataclass
from typing import Union

# 1. Define State Type
@dataclass(frozen=True)
class Idle:
    current_floor: int

@dataclass(frozen=True)
class Moving:
    current_floor: int
    target_floor: int

@dataclass(frozen=True)
class DoorOpen:
    current_floor: int
    timer: int

State = Union[Idle, Moving, DoorOpen]

# 2. Define Event Type
@dataclass(frozen=True)
class Call:
    floor: int

@dataclass(frozen=True)
class Tick:
    pass

@dataclass(frozen=True)
class Arrive:
    pass

Event = Union[Call, Tick, Arrive]

# 3. Implement transition function
def transition(state: State, event: Event) -> State:
    if isinstance(state, Idle) and isinstance(event, Call):
        if event.floor == state.current_floor:
            return DoorOpen(state.current_floor, 3)
        else:
            return Moving(state.current_floor, event.floor)
    elif isinstance(state, Moving) and isinstance(event, Arrive):
        return DoorOpen(state.target_floor, 3)
    elif isinstance(state, DoorOpen) and isinstance(event, Tick):
        if state.timer > 1:
            return DoorOpen(state.current_floor, state.timer - 1)
        else:
            return Idle(state.current_floor)
    else:
        # For any other combination, return the current state unchanged.
        # This covers Moving+Tick, Idle+Tick, etc.
        return state

# 4. Implement display function
def display_state(state: State) -> str:
    if isinstance(state, Idle):
        return f"IDLE @ floor {state.current_floor}"
    elif isinstance(state, Moving):
        return f"MOVING {state.current_floor} -> {state.target_floor}"
    elif isinstance(state, DoorOpen):
        return f"DOOR_OPEN @ floor {state.current_floor} ({state.timer}sec)"
    # This should not be reached with the defined states
    return "UNKNOWN STATE"

# 5. Main simulation
def main() -> None:
    events: list[Event] = [
        Call(5),
        Tick(),
        Tick(),
        Arrive(),
        Tick(),
        Tick(),
        Tick(),
        Tick(),
        Call(1),
    ]

    state: State = Idle(1)

    for event in events:
        state = transition(state, event)
        print(display_state(state))

if __name__ == "__main__":
    main()

