from dataclasses import dataclass
from typing import Union

# 1. Define an expression AST
@dataclass
class Const:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Union[Const, Var, Add, Mul]

# 5. Implement showExpr to convert AST to a readable string
def showExpr(expr: Expr) -> str:
    if isinstance(expr, Const):
        return str(expr.value)
    elif isinstance(expr, Var):
        return expr.name
    elif isinstance(expr, Add):
        return f"({showExpr(expr.left)} + {showExpr(expr.right)})"
    elif isinstance(expr, Mul):
        return f"({showExpr(expr.left)} * {showExpr(expr.right)})"
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

# 2. Implement diff(expr, var)
def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        if expr.name == var:
            return Const(1)
        else:
            return Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        # Product rule: d/dx(f*g) = f*d/dx(g) + g*d/dx(f)
        return Add(
            Mul(expr.left, diff(expr.right, var)),
            Mul(expr.right, diff(expr.left, var))
        )
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

# 3. Implement simplify(expr)
def simplify(expr: Expr) -> Expr:
    # First, recursively simplify children
    if isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)
        expr = Add(left, right)
    elif isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)
        expr = Mul(left, right)

    # Now, apply simplification rules to the current node
    if isinstance(expr, Add):
        if isinstance(expr.left, Const) and expr.left.value == 0:
            return expr.right # 0 + e = e
        if isinstance(expr.right, Const) and expr.right.value == 0:
            return expr.left # e + 0 = e
    elif isinstance(expr, Mul):
        if isinstance(expr.left, Const):
            if expr.left.value == 0:
                return Const(0) # 0 * e = 0
            if expr.left.value == 1:
                return expr.right # 1 * e = e
        if isinstance(expr.right, Const):
            if expr.right.value == 0:
                return Const(0) # e * 0 = 0
            if expr.right.value == 1:
                return expr.left # e * 1 = e

    return expr

def main():
    # 4. Differentiate: x^2 + 3x + 5
    # Represented as: Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    x = Var("x")
    expr = Add(
        Add(
            Mul(x, x),         # x^2
            Mul(Const(3), x)   # 3x
        ),
        Const(5)             # 5
    )

    # Differentiate with respect to "x"
    derivative = diff(expr, "x")

    # Simplify the result
    simplified_derivative = simplify(derivative)

    # 6. Print the simplified derivative using showExpr
    print(showExpr(simplified_derivative))

if __name__ == "__main__":
    main()

