from dataclasses import dataclass
from typing import Callable, TypeVar, Union

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:
        return Node(mapTree(fn, tree.left), fn(tree.value), mapTree(fn, tree.right))

def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:
        acc = foldTree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        acc = foldTree(fn, acc, tree.right)
        return acc

def treeToList(tree: Tree) -> list[int]:
    if isinstance(tree, Leaf):
        return [tree.value]
    else:
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)

def treeDepth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    else:
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))

def double(x: int) -> int:
    return x * 2

def add(x: int, y: int) -> int:
    return x + y

def main():
    tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))

    print(treeToList(tree))
    print(treeToList(mapTree(double, tree)))
    print(foldTree(add, 0, tree))
    print(treeDepth(tree))

if __name__ == "__main__":
    main()

