from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass(frozen=True)
class TVar:
    name: str

@dataclass(frozen=True)
class TInt:
    pass

@dataclass(frozen=True)
class TBool:
    pass

@dataclass(frozen=True)
class TFunc:
    arg: 'Type'
    result: 'Type'

Type = Union[TVar, TInt, TBool, TFunc]
Substitution = List[Tuple[str, Type]]

def apply(subst: Substitution, typ: Type) -> Type:
    if isinstance(typ, TVar):
        for var_name, var_type in subst:
            if var_name == typ.name:
                return var_type
        return typ
    elif isinstance(typ, (TInt, TBool)):
        return typ
    elif isinstance(typ, TFunc):
        return TFunc(apply(subst, typ.arg), apply(subst, typ.result))
    return typ

def compose_subst(s1: Substitution, s2: Substitution) -> Substitution:
    result = [(name, apply(s1, typ)) for name, typ in s2]
    for name, typ in s1:
        if not any(n == name for n, _ in s2):
            result.append((name, typ))
    return result

def unify(t1: Type, t2: Type) -> Substitution:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(apply(s1, t1.result), apply(s1, t2.result))
        return compose_subst(s2, s1)
    else:
        raise ValueError("Cannot unify types")

def type_to_string(typ: Type) -> str:
    if isinstance(typ, TVar):
        return typ.name
    elif isinstance(typ, TInt):
        return "TInt"
    elif isinstance(typ, TBool):
        return "TBool"
    elif isinstance(typ, TFunc):
        return f"TFunc({type_to_string(typ.arg)}, {type_to_string(typ.result)})"
    return str(typ)

if __name__ == "__main__":
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    subst = unify(t1, t2)

    for var_name, var_type in subst:
        print(f"{var_name} = {type_to_string(var_type)}")
